class Solution {
  public String lexPalindromicPermutation(String s, String target) {
    int n = s.length(), h = n / 2;
    int[] cnt = new int[26];
    for (int i = 0; i < n; i++) cnt[s.charAt(i) - 'a']++;
    int odd = 0;
    char mid = 0;
    for (int c = 0; c < 26; c++) {
      if (cnt[c] % 2 == 1) {
        odd++;
        mid = (char) ('a' + c);
      }
      cnt[c] /= 2;
    }
    if (odd > 1) return "";
    int[] rem = cnt.clone();
    // prefix target[0..pos-1] feasible?
    int feasible = 0;
    for (int i = 0; i < h; i++) {
      int c = target.charAt(i) - 'a';
      if (rem[c] == 0) break;
      rem[c]--;
      feasible = i + 1;
    }
    // full tight half
    if (feasible == h) {
      StringBuilder half = new StringBuilder(target.substring(0, h));
      StringBuilder pal = new StringBuilder(half);
      if (mid != 0) pal.append(mid);
      pal.append(new StringBuilder(half).reverse());
      if (pal.toString().compareTo(target) > 0) return pal.toString();
    }
    for (int pos = Math.min(feasible, h - 1); pos >= 0; pos--) {
      // restore counts for prefix of length pos
      int[] cur = cnt.clone();
      for (int i = 0; i < pos; i++) cur[target.charAt(i) - 'a']--;
      int t = target.charAt(pos) - 'a';
      for (int c = t + 1; c < 26; c++) {
        if (cur[c] == 0) continue;
        cur[c]--;
        StringBuilder half = new StringBuilder(target.substring(0, pos));
        half.append((char) ('a' + c));
        for (int x = 0; x < 26; x++) for (int q = 0; q < cur[x]; q++) half.append((char) ('a' + x));
        StringBuilder pal = new StringBuilder(half);
        if (mid != 0) pal.append(mid);
        pal.append(new StringBuilder(half).reverse());
        return pal.toString();
      }
    }
    return "";
  }
}
